"""Authored supplementary explanations; never rewrites course-pack or question IDs.
Run --pilots while UI validation is pending, --all only after pilot sign-off.
"""
import argparse
import copy
import hashlib
import json
import re
import sqlite3
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACK = ROOT / 'content/course-pack.json'
SOURCE_HASH = hashlib.sha256(PACK.read_bytes()).hexdigest()
LESSONS = {x['id']: x for x in json.loads(PACK.read_text(encoding='utf-8'))['lessons']}
DOC = 'https://docs.oracle.com/en/database/oracle/oracle-database/19/sqlrf/'
GUIDES = {}

def tab(title, columns, rows):
    return dict(title=title, columns=columns, rows=[[None if x is None else str(x) for x in row] for row in rows])

def step(title, text, needle=None, table=None, highlights=(), rows=(), cells=(), occurrence=0):
    d = dict(id='', title=title, text=text, codeFocus=[] if not needle else [dict(needle=needle, occurrence=occurrence)], highlights=list(highlights), focusRows=list(rows), focusCells=[dict(row=r,column=c) for r,c in cells])
    if table is not None: d['table']=table
    return d

def term(token, kind, meaning, role): return dict(token=token,kind=kind,meaning=meaning,role=role)

def eg(lid, n, why, effect, prerequisites, steps, comparison, verification=None):
    eid=f'{lid}-E{n:02}' if isinstance(n,int) else n
    for i,s in enumerate(steps,1): s['id']=f'read-{i:02}'
    return dict(exampleId=eid,why=why,effect=effect,prerequisites=prerequisites,steps=steps,comparison=comparison,verification=verification or '원본 값과 문서를 대조한 학습용 설명이다. 이 자료 저술 과정에서 Oracle 엔진은 실행하지 않았다.')

def make(lid,purpose,overview,terms,pitfalls,pages,examples,checks,notes=(),urls=()):
    l=LESSONS[lid]
    assert len(checks)==len(l['selfChecks'])
    g=dict(schemaVersion=1,lessonId=lid,source=copy.deepcopy(l),purpose=purpose,overview=overview,terms=terms,pitfalls=pitfalls,
        questions=[dict(question=f'{t["token"]}는 여기서 무엇을 뜻하나요?',answer=t['role']) for t in terms],
        pdfRefs=[dict(sectionId=l['partId'],title='SQL 기본' if l['partId']=='2-1' else '관리구문과 트랜잭션',fromPage=pages[0],toPage=pages[1],note='흥달쌤 원본 PDF의 해당 절을 확인했다. 아래 앱 예제의 표와 이름은 PDF 예제와 다를 수 있으며 서로 섞지 않는다.')],
        examples=examples,checkGuides=[dict(checkId=q['id'],hint=h,reasoning=r) for q,(h,r) in zip(l['selfChecks'],checks)],sourceUrls=[DOC+u+'.html' for u in urls],reviewNotes=list(notes))
    GUIDES[lid]=g
    return g

def supplement(g,e,guide):
    g.setdefault('supplementalExamples',[]).append(dict(example=e,guide=guide))

def original(lid,n=1): return LESSONS[lid]['examples'][n-1]

