def main():
    ap=argparse.ArgumentParser();ap.add_argument('--pilots',action='store_true');ap.add_argument('--all',action='store_true');ap.add_argument('--independent-review',action='store_true');args=ap.parse_args()
    if args.independent_review:
        record_advanced_review()
        return
    pilots()
    if args.all: remaining()
    scoped_terms()
    polish_text()
    sqlite_reports=verify_sqlite(GUIDES)
    assert args.pilots or args.all
    out=ROOT/'content/lesson-guides';out.mkdir(exist_ok=True)
    reviews=[]
    for lid,g in GUIDES.items():
        validate(g)
        (out/f'{lid}.json').write_text(json.dumps(g,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        reviews.append(dict(lessonId=lid,status='추가 해설',exampleCount=len(g['examples']),checkCount=len(g['checkGuides']),supplementalCount=len(g.get('supplementalExamples',[])),deficiency=REVIEW_GAPS[lid],actions=[g['purpose']],addedReadingSteps=[s['title'] for e in g['examples'] for s in e['steps']],notes=g['reviewNotes'],verification='원문 동일성·참조·강조 범위·표 형상을 검사. 엔진별 실행과 기기 UI는 별도 증거.',unverified=['Oracle DB 엔진 실행', '실제 Galaxy Tab/S Pen', '학습 효과']))
    assert hashlib.sha256(PACK.read_bytes()).hexdigest()==SOURCE_HASH
    ep=ROOT/'evidence/explanation-upgrade-20261012/basic-review.json';ep.parent.mkdir(exist_ok=True,parents=True)
    prior=json.loads(ep.read_text('utf-8')) if ep.exists() else {}
    report=dict(sourceHash=SOURCE_HASH,lessons=reviews,count=len(reviews),scope='pilot' if args.pilots else 'assigned 25 lessons',sqliteExecution=sqlite_reports,limitations=['Oracle engine not run','UI validation is parent task'])
    if 'advancedIndependentReview' in prior:report['advancedIndependentReview']=prior['advancedIndependentReview']
    ep.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(f'Wrote {len(GUIDES)} guides; source unchanged: {SOURCE_HASH}')

if __name__=='__main__': main()
